  pf_section_identity: "நில அடையாளம் மற்றும் இடம்", pf_section_identity_desc: "நிலத்தைப் பதிவு செய்யப்பட்ட விவசாயியுடன் இணைக்கவும். துல்லியமான GPS ஆயத்தொலைவுகள் தேவையில்லை.", pf_plot_id: "நில ID", pf_id_generated: "நிலத்தைச் சேமிக்கும்போது ID உருவாக்கப்படும்.", pf_associated_farmer: "இணைக்கப்பட்ட விவசாயி", pf_select_farmer: "விவசாயியைத் தேர்ந்தெடு", pf_name: "நிலத்தின் பெயர் அல்லது அடையாளம்", pf_name_placeholder: "எ.கா. வடக்கு வயல்", pf_location: "கிராமம் / இடம்", pf_location_placeholder: "கிராமம் மற்றும் உள்ளூர் பகுதி", pf_area: "நிலப் பரப்பளவு", pf_area_placeholder: "0.00", pf_area_unit: "பரப்பளவு அலகு", pf_acre: "ஏக்கர்", pf_hectare: "ஹெக்டேர்",
